def parse_nginx_conf(text):
    servers = []
    # Match server blocks (handling braces)
    # A simple tokenizer/parser for server blocks:
    blocks = re.findall(r"server\s*\{([^\{\}]*(?:\{[^\{\}]*\}[^\{\}]*)*)\}", text, re.DOTALL)
    for b in blocks:
        names = re.findall(r"server_name\s+([^;]+);", b)
        certs = re.findall(r"ssl_certificate\s+([^;]+);", b)
        keys = re.findall(r"ssl_certificate_key\s+([^;]+);", b)
        ports = re.findall(r"listen\s+([^;]+);", b)

        parsed_names = []
        for n in names:
            parsed_names.extend(n.split())

        ssl_cert = certs[0].strip() if certs else None
        ssl_key = keys[0].strip() if keys else None

        servers.append({
            "domains": parsed_names,
            "ports": [p.strip() for p in ports],
            "ssl_certificate": ssl_cert,
            "ssl_key": ssl_key
        })
    return servers

print(parse_nginx_conf(nginx_sample))
